const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define northern Lapland, Sweden region
  const lapland = ee.Geometry.Polygon([
    [[20.0, 68.0], [23.0, 68.0], [23.0, 69.2], [20.0, 69.2], [20.0, 68.0]]
  ]);

  // 2. Cloud masking function for Sentinel-2
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Calculate yellowness index: (Red + Green) / (Blue + 1)
  function addYellowness(image) {
    const yellow = image.select('B4').add(image.select('B3'))
                        .divide(image.select('B2').add(1))
                        .rename('yellowness');
    return image.addBands(yellow);
  }

  // 4. Get September 2016 data
  let septCol = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(lapland)
    .filterDate('2016-09-01', '2016-09-30')
    .map(maskClouds)
    .map(addYellowness);

  const septSize = septCol.size().getInfo();
  console.log('September 2016 images: ' + septSize);

  if (septSize === 0) {
    console.log('No September data, trying Landsat 8');
    septCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lapland)
      .filterDate('2016-09-01', '2016-09-30')
      .map(function(image) {
        const yellow = image.select('SR_B4').add(image.select('SR_B3'))
                            .divide(image.select('SR_B2').add(1))
                            .rename('yellowness');
        return image.addBands(yellow);
      });

    if (septCol.size().getInfo() === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 5. Get October 10, 2016 data
  let octCol = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(lapland)
    .filterDate('2016-10-10', '2016-10-11')
    .map(maskClouds)
    .map(addYellowness);

  const octSize = octCol.size().getInfo();
  console.log('October 10, 2016 images: ' + octSize);

  if (octSize === 0) {
    console.log('No Oct 10 data, trying nearby dates');
    octCol = ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(lapland)
      .filterDate('2016-10-08', '2016-10-12')
      .map(maskClouds)
      .map(addYellowness);

    if (octCol.size().getInfo() === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 6. Calculate mean yellowness for both periods
  const septMean = septCol.select('yellowness').mean();
  const octMean = octCol.select('yellowness').mean();

  // 7. Reduce regions with pixel counting
  const septStats = septMean.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: lapland,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const octStats = octMean.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: lapland,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const septVal = septStats.yellowness_mean;
  const septCount = septStats.yellowness_count;
  const octVal = octStats.yellowness_mean;
  const octCount = octStats.yellowness_count;

  console.log('September yellowness: ' + septVal + ', Pixels: ' + septCount);
  console.log('October yellowness: ' + octVal + ', Pixels: ' + octCount);

  // 8. Validation and answer
  if (septCount === 0 || octCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (septVal === null || octVal === null || isNaN(septVal) || isNaN(octVal)) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (octVal > septVal) {
    console.log('October shows more yellow than September');
    console.log('<answer>A</answer>');
  } else {
    console.log('October does not show more yellow than September');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
